pipeline {
    agent any

    options {
        timestamps()
        ansiColor('xterm')
        buildDiscarder(logRotator(numToKeepStr: '20'))
        disableConcurrentBuilds()
    }

    environment {
        BUILD_DIR = 'build'
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Prepare') {
            steps {
                sh '''
                    set -eux
                    mkdir -p "$BUILD_DIR"
                '''
            }
        }

        stage('Build') {
            steps {
                sh '''
                    set -eux
                    if [ -f Makefile ]; then
                        make build
                    elif [ -f package.json ]; then
                        npm ci
                        npm run build --if-present
                    elif [ -f pom.xml ]; then
                        mvn -B -DskipTests package
                    elif [ -f build.gradle ] || [ -f build.gradle.kts ]; then
                        ./gradlew build -x test
                    else
                        echo "No recognized build file found; add project-specific build commands here."
                    fi
                '''
            }
        }

        stage('Test') {
            steps {
                sh '''
                    set -eux
                    if [ -f Makefile ]; then
                        make test
                    elif [ -f package.json ]; then
                        npm test -- --ci || npm test
                    elif [ -f pom.xml ]; then
                        mvn -B test
                    elif [ -f build.gradle ] || [ -f build.gradle.kts ]; then
                        ./gradlew test
                    else
                        echo "No recognized test command found; add project-specific test commands here."
                    fi
                '''
            }
            post {
                always {
                    junit allowEmptyResults: true, testResults: '**/test-results/**/*.xml, **/surefire-reports/*.xml, **/junit*.xml'
                }
            }
        }

        stage('Archive Artifacts') {
            steps {
                archiveArtifacts artifacts: 'build/**, target/*.jar, target/*.war, dist/**', allowEmptyArchive: true, fingerprint: true
            }
        }
    }

    post {
        success {
            echo 'Build completed successfully.'
        }
        failure {
            echo 'Build failed. Check the console output and test reports.'
        }
        always {
            cleanWs(deleteDirs: true, notFailBuild: true)
        }
    }
}

